const PI = Math.PI;
function rheologyAt(pv,yp,t){const dt=Math.max(0,t-80);return{pv:pv*Math.max(0.3,1-0.005*dt),yp:yp*Math.max(0.2,1-0.004*dt)};}
function hydrostatic(rho,tvd){return 0.052*rho*tvd;}
function annVel(q,dh,dp){const d=dh*dh-dp*dp;return d>0?(q*24.51)/d:0;}
function pipeVel(q,id){return id>0?(q*24.51)/(id*id):0;}
function bRe(rho,v,De,pv){return pv>0&&De>0?(109*rho*v*De)/(300*pv):0;}
function regime(re){return re<2100?"Laminar":re<3000?"Transitional":"Turbulent";}
function annFric(rho,v,len,dh,dp,pv,yp){const De=dh-dp;if(De<=0||v<=0)return{dp:0,re:0,regime:"Laminar"};const re=bRe(rho,v,De,pv);const r=regime(re);const dpdl=re<3000?(pv*v)/(60000*De*De)+yp/(200*De):(0.046/Math.pow(Math.max(re,1),0.2))*rho*v*v/(92903*De);return{dp:dpdl*len,re,regime:r};}
function pipeFric(rho,v,len,id,pv,yp){if(id<=0||v<=0)return{dp:0,re:0,regime:"Laminar"};const re=(928*rho*v*id)/(pv*1000);const r=regime(re);const dpdl=re<3000?(pv*v)/(90000*id*id)+yp/(225*id):(0.046/Math.pow(Math.max(re,1),0.2))*rho*v*v/(92903*id);return{dp:dpdl*len,re,regime:r};}
function ecdAt(rho,fric,tvd){return tvd>0?rho+fric/(0.052*tvd):rho;}
function mobRatio(mpv,myp,cpv,cyp,v,gap){v=Math.max(v,1);const mu=(pv,yp)=>pv+(yp*gap*144)/(v*0.0208*100+1e-6);return mu(cpv,cyp)>0?mu(mpv,myp)/mu(cpv,cyp):10;}
function soCalc(cod,hid,wt,dls,eff){const mc=(hid-cod)/2;if(mc<=0)return 0;return Math.min(100,Math.max(0,((mc-Math.max(0,8.73e-5*wt*dls*12*(1-eff)))/mc)*100));}
function dispEff(displF,dispedF,so,v,len,hid,cod,reg,tContact,temp){const gap=(hid-cod)/2;const{pv:dpv,yp:dyp}=rheologyAt(displF.pv,displF.yp,temp);const{pv:mpv,yp:myp}=rheologyAt(dispedF.pv,dispedF.yp,temp);const base=reg==="Turbulent"?0.92:reg==="Transitional"?0.82:0.72;const vB=0.06*Math.tanh((v-60)/60);const M=mobRatio(myp,myp,dyp,dyp,v,gap);const mF=M<1?0.05*(1-M):M<=2?-0.05*(M-1):Math.max(-0.2,-0.1-0.04*(M-2));const gF=0.03*Math.tanh((displF.density-dispedF.density)/0.5);const ecc=1-so/100;const eP=0.25*Math.pow(ecc,1.5)*(reg==="Turbulent"?0.55:1);const cB=0.02*Math.tanh(tContact/30);const eff=Math.max(0.35,Math.min(0.98,base+vB+mF+gF-eP+cB));const ic=Math.max(0,(hid*hid-cod*cod)/1029.4)*len*(1-eff)*0.5;return{eff,ic};}
function tempAt(d,td,sT,grad,circHr){const stat=sT+grad*d/100;const bhst=sT+grad*td/100;const maxC=Math.min(0.65*(bhst-(sT+10)),35);return stat-maxC*Math.pow(d/Math.max(td,1),0.7)*(1-Math.exp(-0.3*circHr));}
function pipeCap(id){return id*id/1029.4;}
function aCap(hid,od){return Math.max(0,(hid*hid-od*od)/1029.4);}
function computePlug(secs,cF,mF,pLen,setMD,tvdSet,excess){const s=secs.find(x=>x.top_md<=setMD&&setMD<=x.bottom_md)||secs[secs.length-1];const vP=pipeCap(s.casing_id)*pLen,vA=aCap(s.hole_id,s.casing_od)*pLen;const vT=vP+vA;const toc=setMD-pLen;const tocTVD=tvdSet*(toc/setMD);const vD=pipeCap(s.casing_id)*(setMD-pLen);const cushLen=Math.max(50,Math.min(300,0.05*pLen+20*Math.abs(cF.density-mF.density)));const vW=pipeCap(s.casing_id)*cushLen;const dP=Math.abs(0.052*mF.density*tocTVD);const bal=dP<10;const notes=bal?["Balanced plug design within acceptable parameters."]:["Pressure imbalance "+dP.toFixed(1)+" psi — adjust fluid densities."];if(cF.density<=mF.density)notes.push("Cement density ≤ mud density — U-tube risk.");return{plug_length_ft:pLen,set_depth_md_ft:setMD,toc_md_ft:+toc.toFixed(1),toc_tvd_ft:+tocTVD.toFixed(1),cement_volume_in_pipe_bbl:+vP.toFixed(3),cement_volume_in_annulus_bbl:+vA.toFixed(3),total_cement_volume_bbl:+vT.toFixed(3),total_cement_with_excess_bbl:+(vT*excess).toFixed(3),displacement_volume_bbl:+vD.toFixed(3),water_cushion_volume_bbl:+vW.toFixed(3),balance_check_passed:bal,pressure_balance_psi:+dP.toFixed(2),excess_factor_used:excess,design_notes:notes};}
class FluidTracker{constructor(fluids,stages,secs,td){this.fm=Object.fromEntries(fluids.map(f=>[f.name,f]));this.stages=stages;this.secs=secs;this.td=td;this.cv=0;const fn=stages[0]?.fluid_name||"mud";this.pipe=[[fn,0,0]];this.ann=[[fn,0,td]];this.pCap=this._cap(s=>pipeCap(s.casing_id));this.aCap=this._cap(s=>aCap(s.hole_id,s.casing_od));}_cap(fn){const len=this.secs.reduce((a,s)=>a+(s.bottom_md-s.top_md),0);return this.secs.reduce((a,s)=>a+fn(s)*(s.bottom_md-s.top_md),0)/Math.max(len,1)||0.05;}_stage(){let r=0;for(const s of this.stages){if(this.cv<=r+s.volume_bbl)return s;r+=s.volume_bbl;}return this.stages[this.stages.length-1];}advance(dt,rate){if(rate<=0)return;const vol=rate*dt;this.cv+=vol;const st=this._stage();const fa=this.pCap>0?vol/this.pCap:0;const aa=this.aCap>0?vol/this.aCap:0;const top=this.pipe[this.pipe.length-1];if(top[0]!==st.fluid_name)this.pipe.push([st.fluid_name,0,0]);for(const sl of this.pipe)sl[2]=Math.min(this.td,sl[2]+fa);for(const sl of this.pipe){if(sl[2]>=this.td){const ov=(sl[2]-this.td)*this.pCap;const last=this.ann[this.ann.length-1];if(last&&last[0]===sl[0])last[2]+=ov/this.aCap;else this.ann.push([sl[0],this.td-ov/this.aCap,this.td]);sl[2]=this.td;}}for(const sl of this.ann){sl[1]=Math.max(0,sl[1]-aa);sl[2]=Math.max(0,sl[2]-aa);}this.ann=this.ann.filter(s=>s[2]>0);}_dom(arr){const c={};for(const sl of arr)c[sl[0]]=(c[sl[0]]||0)+(sl[2]-sl[1]);const n=Object.entries(c).sort((a,b)=>b[1]-a[1])[0]?.[0];return this.fm[n]||Object.values(this.fm)[0];}domAnn(){return this._dom(this.ann);}domPipe(){return this._dom(this.pipe);}curFluid(){return this.fm[this._stage()?.fluid_name]||Object.values(this.fm)[0];}mudFluid(){return Object.values(this.fm).find(f=>f.fluid_type==="mud")||Object.values(this.fm)[0];}curRate(){return this._stage()?.rate_bbl_min||0;}}
function runSimulation(inp){const{well_geometry:wg,survey,formations,fluids,pump_schedule:ps,temperature:td,centralizer:cent,plug:plg,time_step_min:dt=0.5}=inp;const secs=wg.sections;const TD=wg.total_depth_md;function mdTvd(md){if(!survey.length)return md;for(let i=0;i<survey.length-1;i++){if(survey[i].md<=md&&md<=survey[i+1].md){const f=(md-survey[i].md)/(survey[i+1].md-survey[i].md);return survey[i].tvd+f*(survey[i+1].tvd-survey[i].tvd);}}return survey[survey.length-1].tvd;}function secAt(md){return secs.find(s=>s.top_md<=md&&md<=s.bottom_md)||secs[secs.length-1];}function fracMw(md){const z=formations.find(f=>f.top_md<=md&&md<=f.bottom_md);return z?z.frac_gradient/0.052:999;}const N=40;const nodes=Array.from({length:N+1},(_,i)=>i*TD/N);const totalJobMin=ps.stages.reduce((s,st)=>s+st.volume_bbl/Math.max(st.rate_bbl_min,0.1),0);const repSec=secs[1]||secs[0];const maxIncl=Math.max(...survey.map(s=>s.inclination),0);const centSoArr=nodes.map(d=>soCalc(repSec.casing_od,repSec.hole_id,47,2.0,cent.eff_factor));const avgSo=centSoArr.reduce((a,b)=>a+b,0)/centSoArr.length;const minSo=Math.min(...centSoArr);const recSp=Math.max(20,Math.round(50*cent.eff_factor));const centLocs=[];for(let md=0;md<=Math.min(TD,recSp*10);md+=recSp){const s=secAt(md);const sf=47*(1-fluids[0].density/65.5)*Math.sin(maxIncl*PI/180)*recSp/2;const rest=100*(s.hole_id-s.casing_od)/2*cent.eff_factor;centLocs.push({md_ft:md,standoff_at_centralizer_pct:+Math.min(100,(rest/Math.max(sf,0.001)*100)).toFixed(1),standoff_midspan_pct:+Math.min(100,(rest/Math.max(sf,0.001)*85)).toFixed(1),side_force_lbf:+sf.toFixed(1),spacing_to_next_ft:recSp});}const cF=fluids.find(f=>f.fluid_type==="slurry")||fluids[fluids.length-1];const mF=fluids.find(f=>f.fluid_type==="mud")||fluids[0];const plug=computePlug(secs,cF,mF,plg.plug_length_ft,plg.set_depth_md,mdTvd(plg.set_depth_md),plg.excess_factor);const tracker=new FluidTracker(fluids,ps.stages,secs,TD);const tsT=[],tsP=[],tsE=[],tsB=[],tsD=[],tsV=[];let fHyd=null,fDisp=null,fTemp=null;const warns=new Set();for(let t=0;t<=totalJobMin+dt;t=+(t+dt).toFixed(4)){const rate=tracker.curRate();tracker.advance(dt,rate);const circHr=td.pre_circulation_time_hr+t/60;const tempArr=nodes.map(d=>tempAt(d,TD,td.surface_temp_f,td.geothermal_gradient_f_per_100ft,circHr));const bhct=+tempArr[tempArr.length-1].toFixed(2);const bhst=+(td.surface_temp_f+td.geothermal_gradient_f_per_100ft*TD/100).toFixed(2);const pF=tracker.domPipe(),aF=tracker.domAnn();let cumAF=0,cumPF=0;const ecdArr=[],hydArr=[],pArr=[];const hydSecs=[];let prevMd=0;for(const d of nodes){const s=secAt(d);const tmp=tempAt(d,TD,td.surface_temp_f,td.geothermal_gradient_f_per_100ft,circHr);const{pv:apv,yp:ayp}=rheologyAt(aF.pv,aF.yp,tmp);const segLen=d-prevMd;prevMd=d;const v=annVel(rate,s.hole_id,s.casing_od);const fr=segLen>0?annFric(aF.density,v,segLen,s.hole_id,s.casing_od,apv,ayp):{dp:0,re:0,regime:"Laminar"};cumAF+=fr.dp;const tvd=mdTvd(d);const hy=hydrostatic(aF.density,tvd);pArr.push(+(hy+cumAF).toFixed(1));ecdArr.push(+ecdAt(aF.density,cumAF,tvd).toFixed(3));hydArr.push(+hy.toFixed(1));}for(const s of secs){const mid=(s.top_md+s.bottom_md)/2;const tmp=tempAt(mid,TD,td.surface_temp_f,td.geothermal_gradient_f_per_100ft,circHr);const{pv:apv,yp:ayp}=rheologyAt(aF.pv,aF.yp,tmp);const{pv:ppv,yp:pyp}=rheologyAt(pF.pv,pF.yp,tmp);const v=annVel(rate,s.hole_id,s.casing_od);const pv2=pipeVel(rate,s.casing_id);const af=annFric(aF.density,v,s.bottom_md-s.top_md,s.hole_id,s.casing_od,apv,ayp);const pf=pipeFric(pF.density,pv2,s.bottom_md-s.top_md,s.casing_id,ppv,pyp);cumPF+=pf.dp;hydSecs.push({top_md_ft:s.top_md,bottom_md_ft:s.bottom_md,annular_velocity_ft_min:+v.toFixed(2),annular_reynolds:+af.re.toFixed(0),annular_flow_regime:af.regime,annular_friction_psi:+af.dp.toFixed(2),pipe_velocity_ft_min:+pv2.toFixed(2),pipe_friction_psi:+pf.dp.toFixed(2),ecd_ppg:+ecdAt(aF.density,af.dp,mdTvd(s.bottom_md)).toFixed(3)});}const tvdTD=mdTvd(TD);const surfP=Math.max(0,cumPF+cumAF+(hydrostatic(aF.density,tvdTD)-hydrostatic(pF.density,tvdTD))*0.6);fHyd={total_pipe_friction_psi:+cumPF.toFixed(2),total_annular_friction_psi:+cumAF.toFixed(2),hydrostatic_pressure_psi:+hydrostatic(aF.density,tvdTD).toFixed(2),surface_pump_pressure_psi:+surfP.toFixed(2),max_ecd_ppg:+Math.max(...ecdArr).toFixed(3),min_ecd_ppg:+Math.min(...ecdArr).toFixed(3),sections:hydSecs};let totAV=0,wEff=0;const dSecs=[];for(const s of secs){const mid=(s.top_md+s.bottom_md)/2;const tmp=tempAt(mid,TD,td.surface_temp_f,td.geothermal_gradient_f_per_100ft,circHr);const v=annVel(rate,s.hole_id,s.casing_od);const{pv:apv,yp:ayp}=rheologyAt(aF.pv,aF.yp,tmp);const af=annFric(aF.density,v,1,s.hole_id,s.casing_od,apv,ayp);const so=soCalc(s.casing_od,s.hole_id,47,2.0,cent.eff_factor);const{eff,ic}=dispEff(tracker.curFluid(),tracker.mudFluid(),so,v,s.bottom_md-s.top_md,s.hole_id,s.casing_od,af.regime,t,tmp);const av=aCap(s.hole_id,s.casing_od)*(s.bottom_md-s.top_md);totAV+=av;wEff+=eff*av;dSecs.push({top_md_ft:s.top_md,bottom_md_ft:s.bottom_md,standoff_pct:+so.toFixed(1),annular_velocity_ft_min:+v.toFixed(1),flow_regime:af.regime,mobility_ratio:+(mobRatio(aF.pv,aF.yp,aF.pv*0.9,aF.yp*0.9,Math.max(v,1),(s.hole_id-s.casing_od)/2)).toFixed(3),local_efficiency_pct:+(eff*100).toFixed(2),contamination_pct:+((1-eff)*100).toFixed(2),intermix_volume_bbl:+ic.toFixed(3)});}const oEff=totAV>0?wEff/totAV:0;fDisp={overall_efficiency_pct:+(oEff*100).toFixed(2),overall_contamination_pct:+((1-oEff)*100).toFixed(2),total_intermix_volume_bbl:+dSecs.reduce((s,x)=>s+x.intermix_volume_bbl,0).toFixed(3),poor_displacement_warning:oEff<0.75,sections:dSecs};fTemp={bhct_f:bhct,bhst_f:bhst,surface_temp_f:td.surface_temp_f,temp_gradient_f_per_100ft:td.geothermal_gradient_f_per_100ft,profile:nodes.map(d=>({depth:Math.round(d),temp:+tempAt(d,TD,td.surface_temp_f,td.geothermal_gradient_f_per_100ft,circHr).toFixed(2),static:+(td.surface_temp_f+td.geothermal_gradient_f_per_100ft*d/100).toFixed(2)}))};for(let i=0;i<ecdArr.length;i++){const fg=fracMw(nodes[i]);if(ecdArr[i]>fg)warns.add("ECD "+ecdArr[i].toFixed(2)+" ppg exceeds frac gradient "+fg.toFixed(2)+" ppg at "+Math.round(nodes[i])+" ft MD");}if(oEff<0.75)warns.add("Poor displacement efficiency "+(oEff*100).toFixed(1)+"% — increase pump rate or improve centralization");tsT.push(+t.toFixed(2));tsP.push(+surfP.toFixed(2));tsE.push(+Math.max(...ecdArr).toFixed(3));tsB.push(bhct);tsD.push(+(oEff*100).toFixed(2));tsV.push(+annVel(rate,secs[secs.length-1].hole_id,secs[secs.length-1].casing_od).toFixed(2));if(tracker.cv>=ps.stages.reduce((s,st)=>s+st.volume_bbl,0)&&t>totalJobMin)break;}const warnings=Array.from(warns);if(!warnings.length)warnings.push("No critical warnings. Simulation completed successfully.");return{job_id:inp.job_id,run_time_seconds:0,num_time_steps:tsT.length,total_job_time_min:+totalJobMin.toFixed(2),summary:{well_total_depth_md_ft:TD,bhct_f:fTemp.bhct_f,bhst_f:fTemp.bhst_f,surface_pump_pressure_psi:fHyd.surface_pump_pressure_psi,max_ecd_ppg:fHyd.max_ecd_ppg,displacement_efficiency_pct:fDisp.overall_efficiency_pct,average_standoff_pct:+avgSo.toFixed(1),toc_md_ft:plug.toc_md_ft,total_cement_volume_bbl:plug.total_cement_with_excess_bbl,total_job_time_min:+totalJobMin.toFixed(2),total_volume_pumped_bbl:+tracker.cv.toFixed(2)},warnings,time_series:{time_min:tsT,pump_pressure_psi:tsP,ecd_at_td_ppg:tsE,bhct_f:tsB,displacement_efficiency_pct:tsD,annular_velocity_ft_min:tsV},hydraulics:{...fHyd},displacement:{...fDisp},temperature:{...fTemp},centralizer:{average_standoff_pct:+avgSo.toFixed(1),min_standoff_pct:+minSo.toFixed(1),max_standoff_pct:+Math.max(...centSoArr).toFixed(1),recommended_spacing_ft:recSp,num_centralizers_recommended:Math.ceil(TD/recSp),standoff_below_threshold_pct:+(centSoArr.filter(s=>s<cent.min_standoff_pct).length/centSoArr.length*100).toFixed(1),placement_recommendation:avgSo>=67?"Acceptable standoff achieved. Monitor critical deviated sections.":"CRITICAL: Add centralizers every "+Math.round(recSp*0.6)+" ft in critical intervals.",locations:centLocs},plug,depth_profiles:{depth_ft:nodes,pressure_psi:nodes.map(d=>+hydrostatic(fluids[0].density,mdTvd(d)).toFixed(1)),ecd_ppg:nodes.map(d=>d>0?+ecdAt(fluids[0].density,fHyd.total_annular_friction_psi*d/TD,mdTvd(d)).toFixed(3):fluids[0].density),hydrostatic_psi:nodes.map(d=>+hydrostatic(fluids[0].density,mdTvd(d)).toFixed(1)),temperature_f:nodes.map(d=>+tempAt(d,TD,td.surface_temp_f,td.geothermal_gradient_f_per_100ft,td.pre_circulation_time_hr).toFixed(2)),standoff_pct:centSoArr}};}

