function Bdg({level}){const m={High:["#fce8e8","#a32d2d"],Medium:["#fef3e2","#854f0b"],Low:["#fffbe6","#7a5c00"],Info:["#e6f1fb","#0c447c"],OK:["#e8f5ee","#1a5c35"],Warning:["#fef3e2","#854f0b"],Failed:["#fce8e8","#a32d2d"],Laminar:["#e6f1fb","#0c447c"],Turbulent:["#e8f5ee","#1a5c35"],Transitional:["#fef3e2","#854f0b"]};const[bg,c]=m[level]||m.Info;return <span style={{background:bg,color:c,fontSize:10,fontWeight:500,padding:"2px 8px",borderRadius:4,whiteSpace:"nowrap"}}>{level}</span>;}
function KpiCard({label,value,sub,big}){return <div style={{background:G.bg2,borderRadius:G.r,padding:"10px 12px"}}><div style={{fontSize:10,color:G.text2,marginBottom:3}}>{label}</div><div style={{fontSize:big?22:15,fontWeight:500,color:G.text}}>{value}</div>{sub&&<div style={{fontSize:10,color:G.text3,marginTop:1}}>{sub}</div>}</div>;}
function Card({title,children,style}){return <div style={{background:G.bg,border:`0.5px solid ${G.border}`,borderRadius:G.rLg,overflow:"hidden",...style}}>{title&&<div style={{padding:"9px 14px",borderBottom:`0.5px solid ${G.border}`,fontSize:12,fontWeight:500,color:G.text}}>{title}</div>}<div style={{padding:14}}>{children}</div></div>;}
function FInput({label,value,unit,onChange}){return <div style={{marginBottom:8}}><label style={{fontSize:11,color:G.text2,display:"block",marginBottom:2}}>{label}</label><div style={{display:"flex"}}><input value={value} onChange={e=>onChange(e.target.value)} style={{flex:1,border:`0.5px solid ${G.border2}`,borderRadius:unit?"6px 0 0 6px":G.r,padding:"5px 8px",fontSize:12,background:G.bg,color:G.text,outline:"none",minWidth:0}}/>{unit&&<span style={{background:G.bg2,border:`0.5px solid ${G.border2}`,borderLeft:"none",borderRadius:"0 6px 6px 0",padding:"5px 8px",fontSize:11,color:G.text2,whiteSpace:"nowrap"}}>{unit}</span>}</div></div>;}
function FSel({label,value,options,onChange}){return <div style={{marginBottom:8}}><label style={{fontSize:11,color:G.text2,display:"block",marginBottom:2}}>{label}</label><select value={value} onChange={e=>onChange(e.target.value)} style={{width:"100%",border:`0.5px solid ${G.border2}`,borderRadius:G.r,padding:"5px 8px",fontSize:12,background:G.bg,color:G.text}}>{options.map(o=><option key={o}>{o}</option>)}</select></div>;}
function Topbar({proj="Al Shaheen Well",well="ASH-12",field="North Field"}){return <div style={{height:46,background:G.bg,borderBottom:`0.5px solid ${G.border}`,display:"flex",alignItems:"center",padding:"0 16px",gap:0,flexShrink:0}}><span style={{fontSize:12,color:G.text2}}>Project: <strong style={{color:G.text,fontWeight:500}}>{proj}</strong></span><span style={{color:G.border2,margin:"0 8px"}}>|</span><span style={{fontSize:12,color:G.text2}}>Well: <strong style={{color:G.text,fontWeight:500}}>{well}</strong></span><span style={{color:G.border2,margin:"0 8px"}}>|</span><span style={{fontSize:12,color:G.text2}}>Field: <strong style={{color:G.text,fontWeight:500}}>{field}</strong></span><div style={{flex:1}}/><span style={{fontSize:12,color:G.text2,marginRight:10}}>cemopti ▾</span><button style={{background:"transparent",border:`0.5px solid ${G.border2}`,borderRadius:G.r,padding:"3px 9px",fontSize:11,color:G.text2,cursor:"pointer"}}>?</button></div>;}
const TH=({ch})=><th style={{padding:"6px 10px",background:G.bg2,textAlign:"left",fontSize:10,fontWeight:500,color:G.text2,borderBottom:`0.5px solid ${G.border}`,whiteSpace:"nowrap"}}>{ch}</th>;
const TD2=({ch,mono})=><td style={{padding:"6px 10px",borderBottom:`0.5px solid ${G.border}`,fontSize:11.5,fontFamily:mono?"var(--font-mono)":"inherit"}}>{ch}</td>;

