function LoginPage({onLogin}){const[u,setU]=useState("");const[p,setP]=useState("");const[err,setErr]=useState("");const[loading,setLoading]=useState(false);const attempt=()=>{setLoading(true);setTimeout(()=>{if(u==="cemopti"&&p==="1234"){onLogin();}else{setErr("Invalid username or password.");setLoading(false);}},600);};return <div style={{width:"100%",height:"100%",background:`linear-gradient(135deg,${G.dark} 0%,#1a3d28 60%,#0e2010 100%)`,display:"flex",alignItems:"center",justifyContent:"center",flexDirection:"column"}}><div style={{marginBottom:28,textAlign:"center"}}><div style={{display:"flex",alignItems:"center",justifyContent:"center",gap:12,marginBottom:10}}><div style={{width:48,height:48,background:G.accent,borderRadius:12,display:"flex",alignItems:"center",justifyContent:"center"}}><svg width="28" height="28" viewBox="0 0 28 28" fill="none"><circle cx="14" cy="14" r="9" stroke="#7fe8a8" strokeWidth="2.5"/><circle cx="14" cy="14" r="3.5" fill="#7fe8a8"/><line x1="14" y1="2" x2="14" y2="7" stroke="#7fe8a8" strokeWidth="2"/></svg></div><div style={{fontSize:28,fontWeight:600,color:"#fff",letterSpacing:1}}>Cem<span style={{color:G.accent2}}>OPTI</span></div></div><div style={{fontSize:13,color:"rgba(255,255,255,0.5)",letterSpacing:0.5}}>Cementing Simulation Software</div></div><div style={{background:"rgba(255,255,255,0.06)",border:"0.5px solid rgba(255,255,255,0.12)",borderRadius:16,padding:"32px 36px",width:340,backdropFilter:"blur(8px)"}}><div style={{fontSize:16,fontWeight:500,color:"#fff",marginBottom:4,textAlign:"center"}}>Welcome Back</div><div style={{fontSize:12,color:"rgba(255,255,255,0.4)",marginBottom:24,textAlign:"center"}}>Sign in to your account</div><div style={{marginBottom:14}}><label style={{fontSize:11,color:"rgba(255,255,255,0.6)",display:"block",marginBottom:5}}>Username</label><input value={u} onChange={e=>{setU(e.target.value);setErr("");}} placeholder="Enter username" style={{width:"100%",padding:"9px 12px",borderRadius:8,border:"0.5px solid rgba(255,255,255,0.2)",background:"rgba(255,255,255,0.08)",color:"#fff",fontSize:13,outline:"none",boxSizing:"border-box"}} onKeyDown={e=>e.key==="Enter"&&attempt()}/></div><div style={{marginBottom:20}}><label style={{fontSize:11,color:"rgba(255,255,255,0.6)",display:"block",marginBottom:5}}>Password</label><input type="password" value={p} onChange={e=>{setP(e.target.value);setErr("");}} placeholder="Enter password" style={{width:"100%",padding:"9px 12px",borderRadius:8,border:"0.5px solid rgba(255,255,255,0.2)",background:"rgba(255,255,255,0.08)",color:"#fff",fontSize:13,outline:"none",boxSizing:"border-box"}} onKeyDown={e=>e.key==="Enter"&&attempt()}/></div>{err&&<div style={{background:"rgba(220,50,50,0.15)",border:"0.5px solid rgba(220,50,50,0.4)",borderRadius:6,padding:"7px 10px",fontSize:11,color:"#ff9090",marginBottom:14}}>{err}</div>}<button onClick={attempt} disabled={loading} style={{width:"100%",padding:"10px",background:G.accent,color:"#fff",border:"none",borderRadius:8,fontSize:13,fontWeight:500,cursor:"pointer",opacity:loading?0.7:1}}>{loading?"Signing in...":"Sign In"}</button></div><div style={{marginTop:20,fontSize:11,color:"rgba(255,255,255,0.25)"}}>KemiServe FZE · SPC Freezone, Sharjah, UAE</div></div>;}

// ═══════════════════════════════════════════════════════════════════════
// INPUT PAGE
// ═══════════════════════════════════════════════════════════════════════
const ITABS=[{id:"general",l:"General",n:1},{id:"survey",l:"Survey",n:2},{id:"formation",l:"Formation",n:3},{id:"fluid",l:"Fluid",n:4},{id:"centralizer",l:"Centralizer",n:5},{id:"pumping",l:"Pumping",n:6},{id:"temperature",l:"Temperature",n:7},{id:"displacement",l:"Displacement",n:8},{id:"evaluation",l:"Evaluation",n:9}];
const DONE_TABS=["general","survey","formation","fluid","centralizer","pumping","temperature"];
function InputPage({inp,setInp,onRun,running}){const[tab,setTab]=useState("general");const wg=inp.well_geometry;const td=inp.temperature;const sW=(k,v)=>setInp(p=>({...p,well_geometry:{...p.well_geometry,[k]:+v||0}}));const sT=(k,v)=>setInp(p=>({...p,temperature:{...p.temperature,[k]:+v||0}}));const sF=(i,k,v)=>setInp(p=>{const f=[...p.fluids];f[i]={...f[i],[k]:k==="name"||k==="fluid_type"?v:+v||0};return{...p,fluids:f}});const sC=(k,v)=>setInp(p=>({...p,centralizer:{...p.centralizer,[k]:k==="centralizer_type"?v:+v||0}}));const sP=(k,v)=>setInp(p=>({...p,plug:{...p.plug,[k]:+v||0}}));const sSt=(i,k,v)=>setInp(p=>{const s=[...p.pump_schedule.stages];s[i]={...s[i],[k]:k==="fluid_name"?v:+v||0};return{...p,pump_schedule:{stages:s}}});
const sSurvey=(i,k,v)=>setInp(p=>{const s=[...p.survey];s[i]={...s[i],[k]:+v||0};return{...p,survey:s};});
const sForm=(i,k,v)=>setInp(p=>{const f=[...p.formations];f[i]={...f[i],[k]:+v||0};return{...p,formations:f};});
const pct=Math.round(DONE_TABS.length/ITABS.length*100);const bhst=(td.surface_temp_f+td.geothermal_gradient_f_per_100ft*wg.total_depth_md/100).toFixed(1);const ci=ITABS.findIndex(t=>t.id===tab);
const iStyle={padding:"5px 8px",fontFamily:"var(--font-mono)",fontSize:11,border:`0.5px solid ${G.border2}`,borderRadius:6,background:G.bg,color:G.text,width:"100%",outline:"none",boxSizing:"border-box"};
function form(){switch(tab){case"general":return <div><div style={{fontSize:13,fontWeight:500,color:G.accent,marginBottom:14,paddingBottom:6,borderBottom:`0.5px solid ${G.aBorder}`}}>1. General (Well &amp; Casing)</div><div style={{display:"grid",gridTemplateColumns:"1fr 1fr 1fr",gap:"0 20px"}}><div><FInput label="Total Depth (TVD)" value={wg.total_depth_md} unit="ft" onChange={v=>sW("total_depth_md",v)}/><FInput label="Top of Cement (TOC)" value={wg.top_of_cement_md} unit="ft" onChange={v=>sW("top_of_cement_md",v)}/><FInput label="Shoe Depth (MD)" value={wg.sections[wg.sections.length-1]?.bottom_md} unit="ft" onChange={()=>{}}/><FInput label="Hole Size" value={wg.sections[1]?.hole_id} unit="in" onChange={()=>{}}/><FInput label="Casing OD" value={wg.sections[1]?.casing_od} unit="in" onChange={()=>{}}/></div><div><FInput label="Casing ID" value={wg.sections[1]?.casing_id} unit="in" onChange={()=>{}}/><FInput label="Casing Weight" value="47.00" unit="lb/ft" onChange={()=>{}}/><FInput label="Inclination" value={inp.survey[inp.survey.length-1]?.inclination} unit="deg" onChange={()=>{}}/><FInput label="Azimuth" value={inp.survey[inp.survey.length-1]?.azimuth} unit="deg" onChange={()=>{}}/><FInput label="Dogleg Severity" value="2.00" unit="°/100 ft" onChange={()=>{}}/></div><div><FSel label="Casing Type" value="Single Stage" options={["Single Stage","Two Stage","Liner","Squeeze"]} onChange={()=>{}}/><FSel label="Casing Grade" value="L-80" options={["J-55","K-55","N-80","L-80","P-110","Q-125"]} onChange={()=>{}}/><div style={{marginTop:12,background:G.aLight,border:`0.5px solid ${G.aBorder}`,borderRadius:G.r,padding:10,fontSize:11,color:G.aText}}><strong style={{display:"block",marginBottom:4}}>Field Help</strong>Total vertical depth from rig floor to target.<div style={{color:G.accent2,marginTop:4,fontSize:10}}>Typical Range: 1000 – 25000 ft</div></div></div></div></div>;
case"survey":return <div><div style={{fontSize:13,fontWeight:500,color:G.accent,marginBottom:14,paddingBottom:6,borderBottom:`0.5px solid ${G.aBorder}`}}>2. Survey Data</div><div style={{overflowX:"auto"}}><table style={{width:"100%",borderCollapse:"collapse",fontSize:11}}><thead><tr style={{background:G.bg2}}>{["MD (ft)","TVD (ft)","Inclination (°)","Azimuth (°)"].map(h=><TH key={h} ch={h}/>)}</tr></thead><tbody>{inp.survey.map((s,i)=><tr key={i} style={{borderBottom:`0.5px solid ${G.border}`}}>{[["md","MD (ft)"],["tvd","TVD (ft)"],["inclination","Inclination (°)"],["azimuth","Azimuth (°)"]].map(([k,lbl],c)=><td key={c} style={{padding:"4px 6px"}}><input value={s[k]} onChange={e=>sSurvey(i,k,e.target.value)} style={iStyle}/></td>)}</tr>)}</tbody></table></div></div>;
case"formation":return <div><div style={{fontSize:13,fontWeight:500,color:G.accent,marginBottom:14,paddingBottom:6,borderBottom:`0.5px solid ${G.aBorder}`}}>3. Formation Data</div><div style={{overflowX:"auto"}}><table style={{width:"100%",borderCollapse:"collapse",fontSize:11}}><thead><tr style={{background:G.bg2}}>{["Top MD","Bottom MD","Pore Grad (psi/ft)","Frac Grad (psi/ft)","Perm (mD)","Porosity"].map(h=><TH key={h} ch={h}/>)}</tr></thead><tbody>{inp.formations.map((f,i)=><tr key={i} style={{borderBottom:`0.5px solid ${G.border}`}}>{[["top_md","Top MD"],["bottom_md","Bottom MD"],["pore_pressure_grad","Pore Grad"],["frac_gradient","Frac Grad"],["permeability","Perm"],["porosity","Porosity"]].map(([k,lbl],c)=><td key={c} style={{padding:"4px 6px"}}><input value={f[k]} onChange={e=>sForm(i,k,e.target.value)} style={iStyle}/></td>)}</tr>)}</tbody></table></div></div>;
case"fluid":return <div><div style={{fontSize:13,fontWeight:500,color:G.accent,marginBottom:14,paddingBottom:6,borderBottom:`0.5px solid ${G.aBorder}`}}>4. Fluid Properties</div>{inp.fluids.map((f,i)=><div key={i} style={{marginBottom:16}}><div style={{fontSize:11,fontWeight:500,color:G.text2,marginBottom:8,textTransform:"capitalize"}}>{f.fluid_type} — {f.name}</div><div style={{display:"grid",gridTemplateColumns:"1fr 1fr 1fr 1fr",gap:"0 16px"}}><FInput label="Density" value={f.density} unit="ppg" onChange={v=>sF(i,"density",v)}/><FInput label="PV" value={f.pv} unit="cP" onChange={v=>sF(i,"pv",v)}/><FInput label="YP" value={f.yp} unit="lbf/100ft²" onChange={v=>sF(i,"yp",v)}/><FInput label="Volume" value={f.volume} unit="bbl" onChange={v=>sF(i,"volume",v)}/></div></div>)}</div>;
case"centralizer":return <div><div style={{fontSize:13,fontWeight:500,color:G.accent,marginBottom:14,paddingBottom:6,borderBottom:`0.5px solid ${G.aBorder}`}}>5. Centralizer</div><div style={{display:"grid",gridTemplateColumns:"1fr 1fr 1fr",gap:"0 20px"}}><FSel label="Centralizer Type" value={inp.centralizer.centralizer_type} options={["bow-spring","rigid","semi-rigid","turbo"]} onChange={v=>sC("centralizer_type",v)}/><FInput label="Efficiency Factor (0–1)" value={inp.centralizer.eff_factor} onChange={v=>sC("eff_factor",v)}/><FInput label="Min Standoff %" value={inp.centralizer.min_standoff_pct} unit="%" onChange={v=>sC("min_standoff_pct",v)}/></div></div>;
case"pumping":return <div><div style={{fontSize:13,fontWeight:500,color:G.accent,marginBottom:14,paddingBottom:6,borderBottom:`0.5px solid ${G.aBorder}`}}>6. Pumping Schedule</div>{inp.pump_schedule.stages.map((s,i)=><div key={i} style={{marginBottom:12}}><div style={{fontSize:11,fontWeight:500,color:G.text2,marginBottom:6}}>Stage {i+1} — {s.fluid_name}</div><div style={{display:"grid",gridTemplateColumns:"1fr 1fr 1fr",gap:"0 16px"}}><FInput label="Pump Rate" value={s.rate_bbl_min} unit="bbl/min" onChange={v=>sSt(i,"rate_bbl_min",v)}/><FInput label="Volume" value={s.volume_bbl} unit="bbl" onChange={v=>sSt(i,"volume_bbl",v)}/><FSel label="Fluid" value={s.fluid_name} options={inp.fluids.map(f=>f.name)} onChange={v=>sSt(i,"fluid_name",v)}/></div></div>)}</div>;
case"temperature":return <div><div style={{fontSize:13,fontWeight:500,color:G.accent,marginBottom:14,paddingBottom:6,borderBottom:`0.5px solid ${G.aBorder}`}}>7. Temperature</div><div style={{display:"grid",gridTemplateColumns:"1fr 1fr 1fr",gap:"0 20px"}}><FInput label="Surface Temperature" value={td.surface_temp_f} unit="°F" onChange={v=>sT("surface_temp_f",v)}/><FInput label="Geothermal Gradient" value={td.geothermal_gradient_f_per_100ft} unit="°F/100ft" onChange={v=>sT("geothermal_gradient_f_per_100ft",v)}/><FInput label="Pre-Circulation Time" value={td.pre_circulation_time_hr} unit="hr" onChange={v=>sT("pre_circulation_time_hr",v)}/></div><div style={{marginTop:12,background:G.aLight,border:`0.5px solid ${G.aBorder}`,borderRadius:G.r,padding:10,fontSize:11,color:G.aText}}><strong>Calculated BHST: {bhst} °F</strong> — BHCT typically 20–30°F below BHST during circulation.</div></div>;
case"displacement":return <div><div style={{fontSize:13,fontWeight:500,color:G.accent,marginBottom:14,paddingBottom:6,borderBottom:`0.5px solid ${G.aBorder}`}}>8. Balanced Plug</div><div style={{display:"grid",gridTemplateColumns:"1fr 1fr 1fr",gap:"0 20px"}}><FInput label="Plug Length" value={inp.plug.plug_length_ft} unit="ft" onChange={v=>sP("plug_length_ft",v)}/><FInput label="Set Depth (MD)" value={inp.plug.set_depth_md} unit="ft" onChange={v=>sP("set_depth_md",v)}/><FInput label="Excess Factor" value={inp.plug.excess_factor} onChange={v=>sP("excess_factor",v)}/></div></div>;
default:return <div style={{color:G.text2,fontSize:12}}>Configure parameters for this section.</div>;}}
return <div style={{display:"flex",flexDirection:"column",height:"100%",overflow:"hidden"}}><Topbar/><div style={{background:G.bg,borderBottom:`0.5px solid ${G.border}`,padding:"9px 16px",display:"flex",alignItems:"center",justifyContent:"space-between",flexShrink:0}}><span style={{fontSize:13,fontWeight:500,letterSpacing:0.5}}>INPUT DATA</span><div style={{display:"flex",gap:8,alignItems:"center"}}><span style={{fontSize:11,color:G.text2}}>Unit System:</span><select style={{fontSize:11,padding:"3px 6px",border:`0.5px solid ${G.border2}`,borderRadius:G.r,background:G.bg,color:G.text}}><option>Field Units</option><option>SI Units</option></select><button style={{padding:"4px 10px",border:`0.5px solid ${G.border2}`,borderRadius:G.r,background:G.bg,color:G.text,fontSize:11,cursor:"pointer"}}>Save</button><button style={{padding:"4px 10px",border:`0.5px solid ${G.border2}`,borderRadius:G.r,background:G.bg,color:G.text,fontSize:11,cursor:"pointer"}}>Reset to Default</button><button onClick={onRun} disabled={running} style={{padding:"5px 14px",background:running?"#7aaf8e":G.accent,color:"#fff",border:"none",borderRadius:G.r,fontSize:12,fontWeight:500,cursor:"pointer"}}>{running?"⟳ Running...":"▶ Validate All"}</button></div></div><div style={{display:"flex",background:G.bg,borderBottom:`0.5px solid ${G.border}`,overflowX:"auto",flexShrink:0}}>{ITABS.map(t=><button key={t.id} onClick={()=>setTab(t.id)} style={{display:"flex",alignItems:"center",gap:5,padding:"7px 13px",border:"none",borderBottom:`2px solid ${tab===t.id?G.accent:"transparent"}`,background:"transparent",color:tab===t.id?G.accent:G.text2,fontSize:11.5,fontWeight:tab===t.id?500:400,cursor:"pointer",whiteSpace:"nowrap"}}><span style={{width:17,height:17,borderRadius:"50%",background:tab===t.id?G.accent:G.aLight,color:tab===t.id?"#fff":G.accent,fontSize:9.5,display:"inline-flex",alignItems:"center",justifyContent:"center",fontWeight:500,flexShrink:0}}>{t.n}</span>{t.l}</button>)}</div><div style={{flex:1,display:"flex",overflow:"hidden"}}><div style={{flex:1,padding:16,overflowY:"auto"}}>{form()}</div><div style={{width:176,flexShrink:0,background:G.bg,borderLeft:`0.5px solid ${G.border}`,padding:14,overflowY:"auto"}}><div style={{fontSize:13,fontWeight:500,marginBottom:12}}>Input Summary</div><div style={{display:"flex",flexDirection:"column",alignItems:"center",marginBottom:14}}><svg width="80" height="80" viewBox="0 0 80 80"><circle cx="40" cy="40" r="30" fill="none" stroke={G.aLight} strokeWidth="9"/><circle cx="40" cy="40" r="30" fill="none" stroke={G.accent} strokeWidth="9" strokeDasharray={`${2*PI*30*pct/100} ${2*PI*30}`} strokeLinecap="round" transform="rotate(-90 40 40)"/><text x="40" y="37" textAnchor="middle" fontSize="15" fontWeight="500" fill={G.accent}>{pct}%</text><text x="40" y="51" textAnchor="middle" fontSize="9" fill="#888">Complete</text></svg></div><div style={{marginBottom:14}}>{["General","Survey","Formation","Fluid","Centralizer","Pumping","Temperature","Displacement","Evaluation"].map((c,i)=>{const done=DONE_TABS.includes(c.toLowerCase());return <div key={c} style={{display:"flex",alignItems:"center",gap:6,marginBottom:5}}><div style={{width:14,height:14,borderRadius:"50%",background:done?"#d4f0e0":G.bg2,color:done?G.accent:G.text3,fontSize:9,display:"flex",alignItems:"center",justifyContent:"center",flexShrink:0}}>{done?"✓":""}</div><span style={{fontSize:11.5,color:done?G.text:G.text3}}>{c}</span></div>;})}</div><button onClick={onRun} disabled={running} style={{width:"100%",padding:"7px",background:G.accent,color:"#fff",border:"none",borderRadius:G.r,fontSize:12,fontWeight:500,cursor:"pointer",marginBottom:6}}>{running?"Running...":"▶ Run Simulation"}</button><button style={{width:"100%",padding:"6px",background:"transparent",color:G.accent,border:`0.5px solid ${G.accent}`,borderRadius:G.r,fontSize:11,cursor:"pointer"}}>View Graphs</button></div></div><div style={{display:"flex",justifyContent:"space-between",alignItems:"center",padding:"9px 16px",background:G.bg,borderTop:`0.5px solid ${G.border}`,flexShrink:0}}><button onClick={()=>setTab(ITABS[Math.max(0,ci-1)].id)} disabled={ci===0} style={{padding:"5px 14px",border:`0.5px solid ${G.border2}`,borderRadius:G.r,background:G.bg,color:G.text,fontSize:11,cursor:"pointer"}}>← Previous Tab</button><span style={{fontSize:11,color:G.text3}}>Tab {ci+1} of {ITABS.length}</span><button onClick={()=>setTab(ITABS[Math.min(ITABS.length-1,ci+1)].id)} style={{padding:"5px 14px",background:G.accent,color:"#fff",border:"none",borderRadius:G.r,fontSize:11,cursor:"pointer"}}>Next Tab →</button></div></div>;}

// ═══════════════════════════════════════════════════════════════════════
// WELL SCHEMATIC
// ═══════════════════════════════════════════════════════════════════════
function WellSchematic({results,inputs}){const tvd=inputs.well_geometry.total_depth_md;const toc=results.plug.toc_md_ft;const TH2=360;const sc=TH2/tvd;const tocY=Math.round(toc*sc);const cH=Math.round(inputs.plug.plug_length_ft*sc);const spH=Math.max(8,Math.round(60*sc));const layers=[{y:0,h:tocY-spH-cH,c:"#B5D4F4"},{y:tocY-spH-cH,h:spH,c:"#FAC775"},{y:tocY-cH,h:cH,c:"#97C459"},{y:tocY,h:TH2-tocY,c:"#B4B2A9"}].filter(l=>l.h>0);return <div style={{width:192,flexShrink:0,background:G.bg,borderLeft:`0.5px solid ${G.border}`,padding:12,overflowY:"auto"}}><div style={{fontSize:12,fontWeight:500,marginBottom:10}}>Well Schematic (Fluid Placement)</div><div style={{display:"flex",gap:6}}><div style={{fontSize:9,color:G.text2,textAlign:"right",paddingTop:2,width:34,flexShrink:0}}>0 ft</div><div style={{width:38,position:"relative",height:TH2,border:`0.5px solid ${G.border2}`,borderRadius:2,overflow:"hidden",background:"#f0f0f0",flexShrink:0}}>{layers.map((l,i)=><div key={i} style={{position:"absolute",top:l.y,left:0,right:0,height:l.h,background:l.c,opacity:0.9}}/>)}<div style={{position:"absolute",top:0,left:3,right:3,bottom:0,borderLeft:"2px solid #888",borderRight:"2px solid #888",pointerEvents:"none"}}/></div><div style={{position:"relative",height:TH2,fontSize:9,color:G.text2,width:46}}><div style={{position:"absolute",top:0}}>0</div><div style={{position:"absolute",top:tocY-8,whiteSpace:"nowrap"}}>{toc.toFixed(0)} ft</div><div style={{position:"absolute",bottom:4}}>{tvd} ft</div></div></div><div style={{marginTop:10}}>{[["#B5D4F4","Displacement Fluid"],["#97C459","Cement Slurry"],["#FAC775","Spacer"],["#888780","Mud"]].map(([c,l])=><div key={l} style={{display:"flex",alignItems:"center",gap:6,fontSize:11,color:G.text2,marginBottom:4}}><div style={{width:10,height:10,borderRadius:2,background:c,flexShrink:0}}/>{l}</div>)}</div><div style={{marginTop:12,borderTop:`0.5px solid ${G.border}`,paddingTop:10}}>{[["TOC (Calculated)",`${results.plug.toc_md_ft.toFixed(0)} ft`],["Slurry Volume",`${results.plug.total_cement_volume_bbl.toFixed(0)} bbl`],["Displacement Volume",`${results.plug.displacement_volume_bbl.toFixed(0)} bbl`],["Excess Volume",`${(results.plug.total_cement_with_excess_bbl-results.plug.total_cement_volume_bbl).toFixed(1)} bbl`]].map(([l,v])=><div key={l} style={{marginBottom:8}}><div style={{fontSize:10,color:G.text2}}>{l}</div><div style={{fontSize:13,fontWeight:500}}>{v}</div></div>)}</div></div>;}

