function OutputPage({results,inputs,onBack}){const[tab,setTab]=useState("summary");const r=results;const s=r.summary;const tsD=r.time_series.time_min.map((t,i)=>({t:+t.toFixed(1),pressure:r.time_series.pump_pressure_psi[i],ecd:r.time_series.ecd_at_td_ppg[i],bhct:r.time_series.bhct_f[i],eff:r.time_series.displacement_efficiency_pct[i]})).filter((_,i)=>i%4===0);const ecdDep=r.depth_profiles.depth_ft.map((d,i)=>({depth:Math.round(d),ecd:r.depth_profiles.ecd_ppg[i]||0,frac:(()=>{const z=inputs.formations.find(f=>f.top_md<=d&&d<=f.bottom_md);return z?(z.frac_gradient/0.052).toFixed(2):(inputs.fluids[0].density*1.12).toFixed(2);})()} ));const tempDep=r.temperature.profile.map(p=>({depth:Math.round(p.depth),temp:p.temp,static:p.static}));const soDep=r.depth_profiles.depth_ft.map((d,i)=>({depth:Math.round(d),standoff:r.depth_profiles.standoff_pct[i]}));const warns_dedup=[...new Set(r.warnings.map(w=>w.split(" at t=")[0]))].slice(0,8);const warnRows=[...warns_dedup.filter(w=>w.includes("ECD")).map(w=>({level:"High",param:"ECD",status:"Failed",msg:w})),...warns_dedup.filter(w=>w.includes("displacement")).map(w=>({level:"Medium",param:"Displacement Efficiency",status:"Warning",msg:w})),r.centralizer.min_standoff_pct<r.centralizer.average_standoff_pct*0.8?{level:"Low",param:"Standoff",status:"Warning",msg:`Min standoff ${r.centralizer.min_standoff_pct.toFixed(1)}% below threshold in deviated section`}:null,{level:"Info",param:"BHCT",status:"OK",msg:`BHCT ${s.bhct_f.toFixed(1)} °F — within acceptable limits for cement design`}].filter(Boolean);const stC=(st)=>st==="Failed"?["#fce8e8","#a32d2d"]:st==="Warning"?["#fef3e2","#854f0b"]:["#e8f5ee","#1a5c35"];
function body(){switch(tab){
case"summary":return <><Card title="Warnings"><table style={{width:"100%",borderCollapse:"collapse"}}><thead><tr><TH ch="Level"/><TH ch="Parameter"/><TH ch="Status"/><TH ch="Message"/></tr></thead><tbody>{warnRows.map((w,i)=>{const[sb,sc]=stC(w.status);return <tr key={i} style={{background:i%2===0?G.bg2:G.bg}}><TD2 ch={<Bdg level={w.level}/>}/><TD2 ch={w.param}/><TD2 ch={<span style={{background:sb,color:sc,fontSize:10,padding:"2px 7px",borderRadius:3,fontWeight:500}}>{w.status}</span>}/><TD2 ch={<span style={{fontSize:11,color:G.text2}}>{w.msg}</span>}/></tr>})}</tbody></table></Card><Card title="Engineering Summary"><div style={{display:"grid",gridTemplateColumns:"repeat(4,1fr)",gap:10}}><KpiCard label="Well Depth (TVD)" value={`${s.well_total_depth_md_ft.toLocaleString()} ft`}/><KpiCard label="Mud Weight" value={`${inputs.fluids[0].density.toFixed(2)} ppg`}/><KpiCard label="Pump Rate" value={`${inputs.pump_schedule.stages[0].rate_bbl_min} bpm`}/><KpiCard label="Flow Regime" value={r.hydraulics.sections[r.hydraulics.sections.length-1]?.annular_flow_regime||"—"}/><KpiCard label="Hydrostatic Pressure (Bottom)" value={`${r.hydraulics.hydrostatic_pressure_psi.toLocaleString()} psi`}/><KpiCard label="BHCT (Bottom)" value={`${s.bhct_f.toFixed(1)} °F`}/><KpiCard label="Mobility Ratio" value={r.displacement.sections[0]?.mobility_ratio.toFixed(2)||"—"}/><KpiCard label="TOC (Calculated)" value={`${s.toc_md_ft.toLocaleString()} ft`}/></div></Card><div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:14}}><Card title="Pressure vs Time"><ResponsiveContainer width="100%" height={200}><AreaChart data={tsD} margin={{top:4,right:10,bottom:18,left:10}}><CartesianGrid strokeDasharray="3 3" stroke={G.border} strokeWidth={0.5}/><XAxis dataKey="t" tick={{fontSize:9,fill:"#888"}} label={{value:"Time (min)",position:"insideBottom",offset:-8,fontSize:9,fill:"#888"}}/><YAxis tick={{fontSize:9,fill:"#888"}} tickFormatter={v=>v>=1000?`${(v/1000).toFixed(0)}k`:v}/><Tooltip contentStyle={{fontSize:11,padding:"4px 8px"}} formatter={v=>[`${v.toLocaleString()} psi`,"Surface Pressure"]} labelFormatter={v=>`${v} min`}/><defs><linearGradient id="pg" x1="0" y1="0" x2="0" y2="1"><stop offset="5%" stopColor="#378ADD" stopOpacity={0.2}/><stop offset="95%" stopColor="#378ADD" stopOpacity={0}/></linearGradient></defs><Area type="monotone" dataKey="pressure" stroke="#378ADD" fill="url(#pg)" strokeWidth={2} dot={false} name="Surface Pressure"/></AreaChart></ResponsiveContainer></Card><Card title="ECD vs Depth"><ResponsiveContainer width="100%" height={200}><LineChart data={ecdDep} layout="vertical" margin={{top:4,right:16,bottom:18,left:40}}><CartesianGrid strokeDasharray="3 3" stroke={G.border} strokeWidth={0.5}/><XAxis type="number" dataKey="ecd" domain={["auto","auto"]} tick={{fontSize:9,fill:"#888"}} label={{value:"ECD (ppg)",position:"insideBottom",offset:-10,fontSize:9,fill:"#888"}}/><YAxis type="number" dataKey="depth" tick={{fontSize:9,fill:"#888"}} tickFormatter={v=>v>=1000?`${(v/1000).toFixed(0)}k`:v} reversed/><Tooltip contentStyle={{fontSize:11}} formatter={(v,n)=>[`${v} ppg`,n]} labelFormatter={v=>`${v} ft`}/><Legend wrapperStyle={{fontSize:10}}/><Line type="monotone" dataKey="ecd" stroke="#1a6b3c" strokeWidth={2} dot={false} name="ECD"/><Line type="monotone" dataKey="frac" stroke="#e24b4a" strokeWidth={1.5} strokeDasharray="5 3" dot={false} name="Frac Gradient"/></LineChart></ResponsiveContainer></Card></div><Card title="Hydraulics Overview"><div style={{overflowX:"auto"}}><table style={{width:"100%",borderCollapse:"collapse",fontSize:11}}><thead><tr><TH ch="Depth (ft)"/><TH ch="Hydrostatic (psi)"/><TH ch="Friction (psi)"/><TH ch="Total Pressure (psi)"/><TH ch="ECD (ppg)"/></tr></thead><tbody>{r.depth_profiles.depth_ft.filter((_,i)=>i%8===0).map((d,i)=>{const idx=i*8;const hy=r.depth_profiles.hydrostatic_psi[idx]||0;const pp=r.depth_profiles.pressure_psi[idx]||hy;const fr=pp-hy;const ec=d>0?ecdAt(inputs.fluids[0].density,fr,d*0.99).toFixed(2):inputs.fluids[0].density.toFixed(2);return <tr key={i} style={{background:i%2===0?G.bg2:G.bg}}><TD2 mono ch={Math.round(d).toLocaleString()}/><TD2 mono ch={Math.round(hy).toLocaleString()}/><TD2 mono ch={Math.round(fr).toLocaleString()}/><TD2 mono ch={Math.round(hy+fr).toLocaleString()}/><TD2 mono ch={ec}/></tr>})}</tbody></table></div></Card></>;
case"hydraulics":return <><div style={{display:"grid",gridTemplateColumns:"repeat(4,1fr)",gap:10}}><KpiCard label="Pipe Friction" value={`${r.hydraulics.total_pipe_friction_psi.toFixed(0)} psi`}/><KpiCard label="Annular Friction" value={`${r.hydraulics.total_annular_friction_psi.toFixed(0)} psi`}/><KpiCard label="Surface Pump Pressure" value={`${r.hydraulics.surface_pump_pressure_psi.toFixed(0)} psi`}/><KpiCard label="Max ECD" value={`${r.hydraulics.max_ecd_ppg.toFixed(3)} ppg`}/></div><div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:14}}><Card title="Surface Pressure vs Time"><ResponsiveContainer width="100%" height={200}><AreaChart data={tsD} margin={{top:4,right:10,bottom:18,left:10}}><CartesianGrid strokeDasharray="3 3" stroke={G.border} strokeWidth={0.5}/><XAxis dataKey="t" tick={{fontSize:9}} label={{value:"Time (min)",position:"insideBottom",offset:-8,fontSize:9,fill:"#888"}}/><YAxis tick={{fontSize:9}} tickFormatter={v=>v>=1000?`${(v/1000).toFixed(0)}k`:v}/><Tooltip contentStyle={{fontSize:11}}/><defs><linearGradient id="pg2" x1="0" y1="0" x2="0" y2="1"><stop offset="5%" stopColor="#378ADD" stopOpacity={0.2}/><stop offset="95%" stopColor="#378ADD" stopOpacity={0}/></linearGradient></defs><Area type="monotone" dataKey="pressure" stroke="#378ADD" fill="url(#pg2)" strokeWidth={2} dot={false} name="Pressure (psi)"/></AreaChart></ResponsiveContainer></Card><Card title="ECD vs Depth"><ResponsiveContainer width="100%" height={200}><LineChart data={ecdDep} layout="vertical" margin={{top:4,right:16,bottom:18,left:40}}><CartesianGrid strokeDasharray="3 3" stroke={G.border} strokeWidth={0.5}/><XAxis type="number" domain={["auto","auto"]} tick={{fontSize:9}} label={{value:"ECD (ppg)",position:"insideBottom",offset:-10,fontSize:9,fill:"#888"}}/><YAxis type="number" dataKey="depth" tick={{fontSize:9}} tickFormatter={v=>v>=1000?`${(v/1000).toFixed(0)}k`:v} reversed/><Tooltip contentStyle={{fontSize:11}}/><Legend wrapperStyle={{fontSize:10}}/><Line type="monotone" dataKey="ecd" stroke="#1a6b3c" strokeWidth={2} dot={false} name="ECD"/><Line type="monotone" dataKey="frac" stroke="#e24b4a" strokeWidth={1.5} strokeDasharray="5 3" dot={false} name="Frac Gradient"/></LineChart></ResponsiveContainer></Card></div><Card title="Section Hydraulics Detail"><table style={{width:"100%",borderCollapse:"collapse",fontSize:11}}><thead><tr><TH ch="Interval (ft)"/><TH ch="Ann. Velocity (ft/min)"/><TH ch="Reynolds"/><TH ch="Flow Regime"/><TH ch="Ann. Friction (psi)"/><TH ch="Pipe Friction (psi)"/><TH ch="ECD (ppg)"/></tr></thead><tbody>{r.hydraulics.sections.map((sc,i)=><tr key={i} style={{background:i%2===0?G.bg2:G.bg}}><TD2 mono ch={`${sc.top_md_ft.toLocaleString()}–${sc.bottom_md_ft.toLocaleString()}`}/><TD2 mono ch={sc.annular_velocity_ft_min.toFixed(2)}/><TD2 mono ch={sc.annular_reynolds.toFixed(0)}/><TD2 ch={<Bdg level={sc.annular_flow_regime}/>}/><TD2 mono ch={sc.annular_friction_psi.toFixed(2)}/><TD2 mono ch={sc.pipe_friction_psi.toFixed(2)}/><TD2 mono ch={sc.ecd_ppg.toFixed(3)}/></tr>)}</tbody></table></Card></>;
case"temperature":return <><div style={{display:"grid",gridTemplateColumns:"repeat(4,1fr)",gap:10}}><KpiCard label="BHCT (Circulating)" value={`${r.temperature.bhct_f.toFixed(1)} °F`}/><KpiCard label="BHST (Static)" value={`${r.temperature.bhst_f.toFixed(1)} °F`}/><KpiCard label="BHCT Depression" value={`${(r.temperature.bhst_f-r.temperature.bhct_f).toFixed(1)} °F`}/><KpiCard label="Gradient" value={`${r.temperature.temp_gradient_f_per_100ft} °F/100ft`}/></div><div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:14}}><Card title="Temperature vs Depth"><ResponsiveContainer width="100%" height={240}><LineChart data={tempDep} layout="vertical" margin={{top:4,right:16,bottom:20,left:40}}><CartesianGrid strokeDasharray="3 3" stroke={G.border} strokeWidth={0.5}/><XAxis type="number" domain={["auto","auto"]} tick={{fontSize:9}} label={{value:"Temperature (°F)",position:"insideBottom",offset:-10,fontSize:9,fill:"#888"}}/><YAxis type="number" dataKey="depth" tick={{fontSize:9}} tickFormatter={v=>v>=1000?`${(v/1000).toFixed(0)}k`:v} reversed/><Tooltip contentStyle={{fontSize:11}} formatter={(v,n)=>[`${v.toFixed(1)} °F`,n]} labelFormatter={v=>`${v} ft`}/><Legend wrapperStyle={{fontSize:10}}/><Line type="monotone" dataKey="static" stroke="#e24b4a" strokeWidth={2} dot={false} name="Static (BHST)"/><Line type="monotone" dataKey="temp" stroke="#378ADD" strokeWidth={2} strokeDasharray="5 3" dot={false} name="Circulating (BHCT)"/></LineChart></ResponsiveContainer></Card><Card title="BHCT vs Time"><ResponsiveContainer width="100%" height={240}><LineChart data={tsD} margin={{top:4,right:16,bottom:20,left:10}}><CartesianGrid strokeDasharray="3 3" stroke={G.border} strokeWidth={0.5}/><XAxis dataKey="t" tick={{fontSize:9}} label={{value:"Time (min)",position:"insideBottom",offset:-8,fontSize:9,fill:"#888"}}/><YAxis tick={{fontSize:9}} domain={["auto","auto"]}/><Tooltip contentStyle={{fontSize:11}} formatter={v=>[`${v.toFixed(1)} °F`,"BHCT"]}/><Line type="monotone" dataKey="bhct" stroke="#EF9F27" strokeWidth={2} dot={false} name="BHCT (°F)"/></LineChart></ResponsiveContainer><div style={{marginTop:10,background:G.aLight,border:`0.5px solid ${G.aBorder}`,borderRadius:G.r,padding:9,fontSize:11,color:G.aText}}>Design cement with min 3–4 hr thickening time at BHCT ({r.temperature.bhct_f.toFixed(1)} °F) with 100 Bc.</div></Card></div></>;
case"centralization":return <><div style={{display:"grid",gridTemplateColumns:"repeat(4,1fr)",gap:10}}><KpiCard label="Avg Standoff" value={`${r.centralizer.average_standoff_pct.toFixed(1)}%`}/><KpiCard label="Min Standoff" value={`${r.centralizer.min_standoff_pct.toFixed(1)}%`}/><KpiCard label="Recommended Spacing" value={`${r.centralizer.recommended_spacing_ft} ft`}/><KpiCard label="Centralizers Needed" value={r.centralizer.num_centralizers_recommended}/></div><Card title="Standoff Profile vs Depth"><ResponsiveContainer width="100%" height={220}><LineChart data={soDep} layout="vertical" margin={{top:4,right:16,bottom:20,left:40}}><CartesianGrid strokeDasharray="3 3" stroke={G.border} strokeWidth={0.5}/><XAxis type="number" domain={[0,110]} tick={{fontSize:9}} label={{value:"Standoff (%)",position:"insideBottom",offset:-8,fontSize:9,fill:"#888"}}/><YAxis type="number" dataKey="depth" tick={{fontSize:9}} tickFormatter={v=>v>=1000?`${(v/1000).toFixed(0)}k`:v} reversed/><Tooltip contentStyle={{fontSize:11}} formatter={v=>[`${v.toFixed(1)}%`,"Standoff"]}/><ReferenceLine x={67} stroke="#e24b4a" strokeDasharray="4 3" label={{value:"Min 67%",fontSize:9,fill:"#e24b4a"}}/><Line type="monotone" dataKey="standoff" stroke="#1a6b3c" strokeWidth={2} dot={false} name="Standoff %"/></LineChart></ResponsiveContainer></Card><Card title="Centralizer Locations (first 10)"><table style={{width:"100%",borderCollapse:"collapse",fontSize:11}}><thead><tr><TH ch="MD (ft)"/><TH ch="Standoff @ CL (%)"/><TH ch="Standoff Midspan (%)"/><TH ch="Side Force (lbf)"/><TH ch="Spacing (ft)"/></tr></thead><tbody>{r.centralizer.locations.slice(0,10).map((l,i)=><tr key={i} style={{background:i%2===0?G.bg2:G.bg}}><TD2 mono ch={l.md_ft.toLocaleString()}/><TD2 mono ch={l.standoff_at_centralizer_pct.toFixed(1)}/><TD2 mono ch={l.standoff_midspan_pct.toFixed(1)}/><TD2 mono ch={l.side_force_lbf.toFixed(1)}/><TD2 mono ch={l.spacing_to_next_ft}/></tr>)}</tbody></table></Card><div style={{background:r.centralizer.average_standoff_pct>=67?G.aLight:"#fef3e2",border:`0.5px solid ${r.centralizer.average_standoff_pct>=67?G.aBorder:"#f0c060"}`,borderRadius:G.r,padding:10,fontSize:11.5,color:r.centralizer.average_standoff_pct>=67?G.aText:"#854f0b"}}>{r.centralizer.placement_recommendation}</div></>;
case"displacement":return <><div style={{display:"grid",gridTemplateColumns:"repeat(3,1fr)",gap:10}}><div style={{background:G.bg2,borderRadius:G.r,padding:"12px 14px",textAlign:"center"}}><div style={{fontSize:10,color:G.text2,marginBottom:4}}>Overall Efficiency</div><div style={{fontSize:32,fontWeight:500,color:r.displacement.overall_efficiency_pct>80?G.success:r.displacement.overall_efficiency_pct>65?"#854f0b":G.danger}}>{r.displacement.overall_efficiency_pct.toFixed(1)}%</div></div><KpiCard label="Contamination" value={`${r.displacement.overall_contamination_pct.toFixed(1)}%`}/><KpiCard label="Total Intermix Volume" value={`${r.displacement.total_intermix_volume_bbl.toFixed(1)} bbl`}/></div><div style={{height:6,background:G.bg2,borderRadius:3,overflow:"hidden"}}><div style={{height:"100%",width:`${r.displacement.overall_efficiency_pct}%`,background:r.displacement.overall_efficiency_pct>80?"#0F6E56":r.displacement.overall_efficiency_pct>65?"#854F0B":"#A32D2D",borderRadius:3}}/></div><div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:14}}><Card title="Displacement Efficiency vs Time"><ResponsiveContainer width="100%" height={200}><AreaChart data={tsD} margin={{top:4,right:10,bottom:18,left:10}}><CartesianGrid strokeDasharray="3 3" stroke={G.border} strokeWidth={0.5}/><XAxis dataKey="t" tick={{fontSize:9}} label={{value:"Time (min)",position:"insideBottom",offset:-8,fontSize:9,fill:"#888"}}/><YAxis tick={{fontSize:9}} domain={[40,100]}/><Tooltip contentStyle={{fontSize:11}} formatter={v=>[`${v.toFixed(1)}%`,"Efficiency"]}/><ReferenceLine y={75} stroke="#e24b4a" strokeDasharray="4 3"/><defs><linearGradient id="dg" x1="0" y1="0" x2="0" y2="1"><stop offset="5%" stopColor="#1a6b3c" stopOpacity={0.2}/><stop offset="95%" stopColor="#1a6b3c" stopOpacity={0}/></linearGradient></defs><Area type="monotone" dataKey="eff" stroke="#1a6b3c" fill="url(#dg)" strokeWidth={2} dot={false} name="Efficiency %"/></AreaChart></ResponsiveContainer></Card><Card title="Section Displacement Detail"><table style={{width:"100%",borderCollapse:"collapse",fontSize:11}}><thead><tr><TH ch="Section (ft)"/><TH ch="Regime"/><TH ch="Ann. Vel."/><TH ch="Standoff"/><TH ch="Efficiency"/></tr></thead><tbody>{r.displacement.sections.map((sc,i)=><tr key={i} style={{background:i%2===0?G.bg2:G.bg}}><TD2 mono ch={`${sc.top_md_ft.toLocaleString()}–${sc.bottom_md_ft.toLocaleString()}`}/><TD2 ch={<Bdg level={sc.flow_regime}/>}/><TD2 mono ch={`${sc.annular_velocity_ft_min.toFixed(1)} ft/min`}/><TD2 mono ch={`${sc.standoff_pct.toFixed(0)}%`}/><TD2 mono ch={<span style={{color:sc.local_efficiency_pct>80?G.success:sc.local_efficiency_pct>65?"#854f0b":G.danger,fontWeight:500}}>{sc.local_efficiency_pct.toFixed(1)}%</span>}/></tr>)}</tbody></table></Card></div></>;
case"plug":return <><div style={{display:"grid",gridTemplateColumns:"repeat(4,1fr)",gap:10}}><KpiCard label="Plug Length" value={`${r.plug.plug_length_ft.toFixed(0)} ft`}/><KpiCard label="Set Depth (MD)" value={`${r.plug.set_depth_md_ft.toLocaleString()} ft`}/><KpiCard label="TOC (MD)" value={`${r.plug.toc_md_ft.toLocaleString()} ft`}/><KpiCard label="TOC (TVD)" value={`${r.plug.toc_tvd_ft.toLocaleString()} ft`}/></div><div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:14}}><Card title="Volume Summary"><table style={{width:"100%",borderCollapse:"collapse",fontSize:11}}><tbody>{[["Cement in Pipe",`${r.plug.cement_volume_in_pipe_bbl.toFixed(3)} bbl`],["Cement in Annulus",`${r.plug.cement_volume_in_annulus_bbl.toFixed(3)} bbl`],["Total Cement Volume",`${r.plug.total_cement_volume_bbl.toFixed(3)} bbl`],["Total w/ Excess",`${r.plug.total_cement_with_excess_bbl.toFixed(3)} bbl`],["Displacement Volume",`${r.plug.displacement_volume_bbl.toFixed(2)} bbl`],["Water Cushion",`${r.plug.water_cushion_volume_bbl.toFixed(3)} bbl`],["Excess Factor",r.plug.excess_factor_used.toFixed(2)]].map(([l,v],i)=>(<tr key={i} style={{background:i%2===0?G.bg2:G.bg}}><td style={{padding:"6px 10px",borderBottom:`0.5px solid ${G.border}`,fontSize:11,color:G.text2}}>{l}</td><td style={{padding:"6px 10px",borderBottom:`0.5px solid ${G.border}`,fontSize:11,fontFamily:"var(--font-mono)",fontWeight:500}}>{v}</td></tr>))}</tbody></table></Card><Card title="Balance Check"><div style={{textAlign:"center",padding:"16px 0 12px"}}><div style={{fontSize:40,marginBottom:6}}>{r.plug.balance_check_passed?"✓":"✗"}</div><div style={{fontSize:16,fontWeight:500,color:r.plug.balance_check_passed?G.success:G.danger}}>{r.plug.balance_check_passed?"PASS — Balanced":"FAIL — Imbalanced"}</div><div style={{fontSize:12,color:G.text2,marginTop:4}}>Pressure imbalance: {r.plug.pressure_balance_psi.toFixed(2)} psi</div></div>{r.plug.design_notes.map((n,i)=>(<div key={i} style={{background:r.plug.balance_check_passed?G.aLight:"#fef3e2",border:`0.5px solid ${r.plug.balance_check_passed?G.aBorder:"#f0c060"}`,borderRadius:G.r,padding:9,fontSize:11,color:r.plug.balance_check_passed?G.aText:"#854f0b",marginTop:8}}>{n}</div>))}</Card></div></>;
default:return null;}}
return <div style={{display:"flex",flexDirection:"column",height:"100%",overflow:"hidden"}}><Topbar/><div style={{background:G.bg,borderBottom:`0.5px solid ${G.border}`,padding:"9px 16px",display:"flex",alignItems:"center",justifyContent:"space-between",flexShrink:0}}><div style={{display:"flex",alignItems:"center",gap:12}}><span style={{fontSize:11,color:G.text3}}>— {r.num_time_steps} steps · {r.total_job_time_min.toFixed(1)} min · {r.run_time_seconds.toFixed(3)}s compute</span></div><div style={{display:"flex",gap:8}}><button onClick={onBack} style={{padding:"5px 12px",border:`0.5px solid ${G.border2}`,borderRadius:G.r,background:G.bg,color:G.text,fontSize:11,cursor:"pointer"}}>← Edit Inputs</button><button onClick={()=>generateReport(results,inputs)} style={{padding:"5px 12px",border:`0.5px solid ${G.accent}`,borderRadius:G.r,background:"transparent",color:G.accent,fontSize:11,cursor:"pointer"}}>🖨 Generate Report (PDF)</button></div></div><div style={{display:"flex",background:G.bg,borderBottom:`0.5px solid ${G.border}`,overflowX:"auto",flexShrink:0}}>{OTABS.map(t=><button key={t.id} onClick={()=>setTab(t.id)} style={{padding:"8px 14px",border:"none",borderBottom:`2px solid ${tab===t.id?G.accent:"transparent"}`,background:"transparent",color:tab===t.id?G.accent:G.text2,fontSize:12,fontWeight:tab===t.id?500:400,cursor:"pointer",whiteSpace:"nowrap"}}>{t.l}</button>)}</div><div style={{flex:1,display:"flex",overflow:"hidden"}}><div style={{flex:1,padding:14,overflowY:"auto",display:"flex",flexDirection:"column",gap:14}}>{body()}</div><WellSchematic results={r} inputs={inputs}/></div></div>;}

