// MANUAL PAGE
// ═══════════════════════════════════════════════════════════════════════
function ManualPage(){const[tab,setTab]=useState("user");
const sections=[{id:"user",l:"User Manual"},{id:"tech",l:"Technical Manual"}];
return <div style={{display:"flex",flexDirection:"column",height:"100%",overflow:"hidden"}}><Topbar/><div style={{background:G.bg,borderBottom:`0.5px solid ${G.border}`,padding:"9px 16px",flexShrink:0}}><span style={{fontSize:13,fontWeight:500}}>Manual</span></div><div style={{display:"flex",background:G.bg,borderBottom:`0.5px solid ${G.border}`,flexShrink:0}}>{sections.map(s=><button key={s.id} onClick={()=>setTab(s.id)} style={{padding:"8px 18px",border:"none",borderBottom:`2px solid ${tab===s.id?G.accent:"transparent"}`,background:"transparent",color:tab===s.id?G.accent:G.text2,fontSize:12,fontWeight:tab===s.id?500:400,cursor:"pointer"}}>{s.l}</button>)}</div>
<div style={{flex:1,overflowY:"auto",padding:24}}>
{tab==="user"?<div style={{maxWidth:760}}>
  <h2 style={{fontSize:17,fontWeight:600,color:G.accent,marginBottom:6}}>CemOPTI — User Manual</h2>
  <p style={{color:G.text2,fontSize:12,marginBottom:20}}>Version 1.0 · KemiServe FZE</p>
  {[["Getting Started","CemOPTI is a browser-based cementing simulation tool. After login, you are directed to the Dashboard. Navigate using the left sidebar. To run a simulation: (1) Click 'Input Data', (2) Fill in all 9 input tabs, (3) Click 'Run Simulation'."],["Dashboard","Provides an overview of active projects, recent simulations, and key performance metrics. Click 'Open' on any project to jump directly to its Input Data page."],["Input Data — General","Enter the well total depth (TVD), top of cement (TOC), casing dimensions, inclination and azimuth values. Select casing type and grade from the dropdowns."],["Input Data — Survey","Enter measured depth (MD), true vertical depth (TVD), inclination and azimuth for each survey station. All cells are directly editable."],["Input Data — Formation","Define formation intervals by top/bottom MD along with pore pressure gradient, fracture gradient, permeability, porosity, and temperature gradient. All cells are editable."],["Input Data — Fluid","Enter density (ppg), plastic viscosity (PV in cP), yield point (YP in lbf/100ft²) and planned volume (bbl) for each fluid: mud, spacer, slurry, and displacement fluid."],["Input Data — Centralizer","Select centralizer type, input the efficiency factor (0–1) and minimum acceptable standoff percentage. CemOPTI calculates optimum centralizer spacing."],["Input Data — Pumping","Define the pump schedule stages: fluid name, rate (bbl/min), and planned volume (bbl). Stages are executed in sequence during simulation."],["Input Data — Temperature","Set surface temperature, geothermal gradient (°F/100ft) and pre-circulation time (hours). The BHST is auto-calculated and displayed."],["Input Data — Displacement / Plug","Define the balanced plug: plug length (ft), set depth (MD), and excess factor for volume calculation."],["Run Simulation","Click 'Run Simulation' in the sidebar or via the Validate All button. The engine runs all 5 modules and redirects to Output Results."],["Output Results","Navigate using the 6 output tabs: Summary, Hydraulics, Temperature, Centralization, Displacement Efficiency, and Balanced Plug. The Well Schematic panel on the right shows fluid placement."],["Generate Report","Click 'Generate Report (PDF)' on the Output Results page. A print-formatted 10-page report opens in a new tab. Use your browser's Print → Save as PDF function to export."]].map(([t,c],i)=><div key={i} style={{marginBottom:16,borderLeft:`3px solid ${G.accent}`,paddingLeft:14}}><div style={{fontWeight:500,fontSize:13,marginBottom:4,color:G.text}}>{t}</div><div style={{fontSize:12,color:G.text2,lineHeight:1.7}}>{c}</div></div>)}
</div>:
<div style={{maxWidth:820}}>
  <h2 style={{fontSize:17,fontWeight:600,color:G.accent,marginBottom:6}}>CemOPTI — Technical Manual</h2>
  <p style={{color:G.text2,fontSize:12,marginBottom:20}}>Equations, Models &amp; References for each simulation module</p>
  {[{title:"Module 1 — Hydraulics",items:[["Hydrostatic Pressure","P_hyd = 0.052 × ρ × TVD  [psi]  where ρ = fluid density (ppg), TVD = true vertical depth (ft). Factor 0.052 converts ppg·ft to psi.","Bourgoyne et al., Applied Drilling Engineering, SPE Textbook Vol. 2, 1986"],["Annular Velocity","V_ann = (Q × 24.51) / (D_h² − D_p²)  [ft/min]  where Q = flow rate (gal/min), D_h = hole diameter (in), D_p = pipe OD (in).","API RP 10D-2, Centralization of Casing, 2004"],["Bingham Plastic Reynolds Number","Re = (109 × ρ × V × D_e) / (300 × PV)  where D_e = D_h − D_p = equivalent diameter (in), PV = plastic viscosity (cP).","Bourgoyne et al., 1986; API RP 13D"],["Annular Friction Pressure (Laminar/Transitional)","ΔP = [PV × V / (60000 × D_e²)] + [YP / (200 × D_e)] × L  where YP = yield point, L = interval length (ft).","API RP 13D, Rheology and Hydraulics of Oil-Well Fluids"],["Annular Friction Pressure (Turbulent)","ΔP = [0.046 / Re^0.2] × ρ × V² / (92903 × D_e) × L","Dodge & Metzner turbulent flow correlation, SPE-1478, 1959"],["Equivalent Circulating Density","ECD = ρ + ΔP_ann / (0.052 × TVD)  [ppg]","API RP 10D-2; Bourgoyne et al., 1986"]]},{title:"Module 2 — Temperature",items:[["BHST (Static)","T_BHST = T_surface + G × TVD/100  where G = geothermal gradient (°F/100ft).","Ramey (1962), Wellbore Heat Transmission, JPT"],["BHCT (Circulating)","T_BHCT = T_static − ΔT_max × (d/TD)^0.7 × (1 − e^(−0.3 × t_circ))  where ΔT_max = cooling depression, t_circ = circulation time (hr).","Ramey (1962); Holmes & Swift (1970), JPT"],["Temperature Depression","ΔT_max = min(0.65 × (BHST − T_surface − 10), 35)  — limits cooling to realistic range.","Field correlation, Rommetveit & Vefring, 1991"]]},{title:"Module 3 — Displacement Efficiency",items:[["Base Efficiency by Regime","E_base = 0.72 (Laminar), 0.82 (Transitional), 0.92 (Turbulent) — fundamental displacement quality as a function of flow regime.","McLean et al., Displacement Mechanics in Primary Cementing, JPT 1967"],["Velocity Correction","ΔE_v = 0.06 × tanh((V − 60)/60) — improvement in efficiency with increasing annular velocity.","Zuiderwijk (1975), Mud Displacement in Primary Cementation"],["Mobility Ratio Correction","M = μ_mud / μ_cement  (effective viscosity at annular shear rate). ΔE_M > 0 when M < 1 (favorable), negative when M > 2.","Tehrani et al., Fluid Displacement in Primary Cementing, SPE-20680, 1992"],["Standoff Correction","ΔE_so = −0.25 × ((1 − SO/100)^1.5) × (0.55 if turbulent, else 1.0)","Keller et al., SPE-9285, 1987; API RP 10D-2"],["Density Contrast Correction","ΔE_ρ = 0.03 × tanh((ρ_disp − ρ_mud)/0.5) — positive effect of heavier displacement fluid.","Lockyear & Hibbert, SPE-18376, 1989"]]},{title:"Module 4 — Centralization",items:[["Standoff Percentage","SO = [(r_h − r_c)/2 − δ] / [(r_h − r_c)/2] × 100  where δ = casing offset due to side force and bending.","API RP 10D-2, 2004"],["Side Force on Casing","F_side = W_pipe × DLS × L_interval × sin(θ)  — side force from casing weight, dogleg severity, interval length, and inclination.","API RP 10D-2; Juvkam-Wold & Wu, SPE-23909"],["Recommended Spacing","L_spacing = max(20, 50 × eff_factor)  [ft] — empirical relationship between centralizer efficiency and placement frequency.","Field engineering practice, API RP 10D-2"]]},{title:"Module 5 — Balanced Plug",items:[["Volume in Pipe","V_pipe = (ID²/1029.4) × L_plug  [bbl] — capacity of drill pipe or casing ID.","Casing/Tubular Handbook, API Spec 5CT"],["Volume in Annulus","V_ann = (D_h² − OD²) / 1029.4 × L_plug  [bbl]","API Spec 5CT; cementing engineering calculations"],["Balanced Condition","Balanced plug: hydrostatic pressure of cement column equals hydrostatic of surrounding fluid at the plug base. ΔP = |0.052 × ρ_mud × TOC_TVD|. PASS if ΔP < 10 psi.","Nelson & Guillot, Well Cementing, Schlumberger 2006"],["Water Cushion Volume","V_wc = (ID²/1029.4) × L_cushion  where L_cushion = max(50, min(300, 0.05×L_plug + 20×|ρ_cement − ρ_mud|)).","Nelson & Guillot, Well Cementing, 2006; industry practice"]]}].map((mod,mi)=><div key={mi} style={{marginBottom:26}}><div style={{background:G.aLight,border:`0.5px solid ${G.aBorder}`,borderRadius:8,padding:"8px 16px",marginBottom:12}}><span style={{fontWeight:600,color:G.accent,fontSize:13}}>{mod.title}</span></div>{mod.items.map(([name,eq,ref],j)=><div key={j} style={{marginBottom:14,paddingLeft:16,borderLeft:`2px solid ${G.border2}`}}><div style={{fontWeight:500,fontSize:12,color:G.text,marginBottom:3}}>{name}</div><div style={{fontFamily:"var(--font-mono)",fontSize:11,background:G.bg2,padding:"6px 10px",borderRadius:6,color:G.text,marginBottom:4,lineHeight:1.8}}>{eq}</div><div style={{fontSize:10.5,color:G.text3,fontStyle:"italic"}}>Ref: {ref}</div></div>)}</div>)}
</div>}
</div></div>;}

