// HELP PAGE
// ═══════════════════════════════════════════════════════════════════════
function HelpPage(){return <div style={{display:"flex",flexDirection:"column",height:"100%",overflow:"hidden"}}><Topbar/><div style={{background:G.bg,borderBottom:`0.5px solid ${G.border}`,padding:"9px 16px",flexShrink:0}}><span style={{fontSize:13,fontWeight:500}}>Help &amp; Support</span></div><div style={{flex:1,overflowY:"auto",padding:24}}><div style={{maxWidth:600}}><div style={{background:G.aLight,border:`0.5px solid ${G.aBorder}`,borderRadius:12,padding:"28px 32px",marginBottom:24}}><div style={{fontSize:18,fontWeight:600,color:G.accent,marginBottom:4}}>KemiServe FZE</div><div style={{fontSize:13,color:G.text2,marginBottom:18}}>Cementing Simulation Software · CemOPTI v1.0</div>{[["📍 Address","SPC Freezone, Sharjah, UAE"],["✉️ Email","info@kemisim.com"],["🌐 Product","CemOPTI — Cementing Simulation Software"],["🏢 Entity","KemiServe FZE"]].map(([l,v])=><div key={l} style={{display:"flex",gap:12,marginBottom:10,alignItems:"flex-start"}}><span style={{minWidth:100,fontSize:12,color:G.text2}}>{l}</span><span style={{fontSize:12,fontWeight:500,color:G.text}}>{v}</span></div>)}</div><Card title="Frequently Asked Questions">{[["How do I run a simulation?","Navigate to Input Data via the left sidebar, fill in all required tabs, then click 'Run Simulation'. Results appear automatically in Output Results."],["How do I export a report?","After running a simulation, go to Output Results and click 'Generate Report (PDF)'. A formatted report opens in a new tab — use your browser's Print → Save as PDF."],["Can I edit survey and formation data?","Yes — on the Survey and Formation input tabs, all table cells are directly editable."],["What units does CemOPTI use?","CemOPTI uses Field Units (ppg, ft, °F, bbl, psi, cP). SI unit support is planned for a future release."],["Who do I contact for technical support?","Please email info@kemisim.com with your job ID and a description of the issue."]].map(([q,a],i)=><div key={i} style={{marginBottom:16,paddingBottom:16,borderBottom:i<4?`0.5px solid ${G.border}`:"none"}}><div style={{fontWeight:500,fontSize:12,marginBottom:4,color:G.text}}>{q}</div><div style={{fontSize:12,color:G.text2,lineHeight:1.7}}>{a}</div></div>)}</Card></div></div></div>;}

// ═══════════════════════════════════════════════════════════════════════
// CASE STUDY PAGE
// ═══════════════════════════════════════════════════════════════════════
function CaseStudyPage(){return <div style={{display:"flex",flexDirection:"column",height:"100%",overflow:"hidden"}}><Topbar/><div style={{background:G.bg,borderBottom:`0.5px solid ${G.border}`,padding:"9px 16px",flexShrink:0}}><span style={{fontSize:13,fontWeight:500}}>Case Study</span></div><div style={{flex:1,overflowY:"auto",padding:24}}><div style={{maxWidth:720}}><h2 style={{fontSize:15,fontWeight:600,color:G.accent,marginBottom:6}}>Case Study: Al Shaheen Well ASH-12</h2><p style={{fontSize:12,color:G.text2,marginBottom:18}}>North Field, Offshore UAE — 9⅝" Production Casing Cement Job</p><Card title="Background"><p style={{fontSize:12,color:G.text2,lineHeight:1.8}}>Well ASH-12 is a mildly deviated well reaching 8,000 ft MD (7,900 ft TVD) targeting the North Field reservoir. The 9⅝" production casing cement job was critical to isolate a high-permeability zone (2.0 mD) at 6,000–8,000 ft MD. Poor zonal isolation in previous wells in the same field had led to unwanted gas migration, making optimal cement placement paramount.</p></Card><Card title="Challenges Identified" style={{marginTop:14}}>{[["Temperature","BHST of 195°F required careful selection of cement retarder to achieve adequate thickening time without compromising compressive strength development."],["ECD Control","Narrow window between pore pressure gradient (0.478 psi/ft) and fracture gradient (0.76 psi/ft) required close monitoring of pump rate and ECD."],["Displacement Efficiency","Mild deviation (up to 9°) and suboptimal standoff risk created channeling of cement — addressed through turbulent flow regime design."]].map(([t,c],i)=><div key={i} style={{marginBottom:12,paddingLeft:12,borderLeft:`3px solid ${G.accent}`}}><div style={{fontWeight:500,fontSize:12,marginBottom:2}}>{t}</div><div style={{fontSize:12,color:G.text2,lineHeight:1.7}}>{c}</div></div>)}</Card><Card title="Simulation Results" style={{marginTop:14}}><div style={{display:"grid",gridTemplateColumns:"1fr 1fr 1fr",gap:10}}><KpiCard label="BHCT Achieved" value="162.3 °F"/><KpiCard label="Max ECD" value="13.085 ppg"/><KpiCard label="Displacement Eff." value="87.4%"/><KpiCard label="Avg Standoff" value="72.3%"/><KpiCard label="TOC (MD)" value="7,650 ft"/><KpiCard label="Total Cement" value="322 bbl"/></div></Card><Card title="Lessons Learned" style={{marginTop:14}}>{["Pre-circulation of 4 hours reduced BHCT by ~33°F, significantly improving cement retarder design safety margin.","Turbulent flow regime in all sections (Re > 3,000) yielded >85% displacement efficiency, exceeding the 80% target.","Recommended centralizer spacing of 38 ft with 75% efficiency factor achieved average standoff of 72.3%, above the API minimum of 67%.","Balanced plug design passed pressure balance check with <1 psi imbalance, confirming safe plug placement."].map((l,i)=><div key={i} style={{display:"flex",gap:8,marginBottom:8,fontSize:12,color:G.text2,alignItems:"flex-start"}}><span style={{color:G.accent,flexShrink:0,marginTop:2}}>✓</span>{l}</div>)}</Card></div></div></div>;}

