// DASHBOARD
// ═══════════════════════════════════════════════════════════════════════
function Dashboard({onNav}){return <div style={{display:"flex",flexDirection:"column",height:"100%",overflow:"hidden"}}><Topbar/><div style={{flex:1,padding:18,overflowY:"auto"}}><div style={{fontSize:15,fontWeight:500,marginBottom:14}}>Dashboard</div><div style={{display:"grid",gridTemplateColumns:"repeat(4,1fr)",gap:12,marginBottom:18}}><KpiCard label="Active Projects" value="3"/><KpiCard label="Simulations Run" value="12"/><KpiCard label="Pending Reports" value="2"/><KpiCard label="Last Job" value="ASH-12"/></div><Card title="Recent Projects"><table style={{width:"100%",borderCollapse:"collapse",fontSize:12}}><thead><tr style={{background:G.bg2}}>{["Project","Well","Field","Status","Action"].map(h=><TH key={h} ch={h}/>)}</tr></thead><tbody>{[["Al Shaheen Well","ASH-12","North Field","Active"],["Eagle Ford #14","EF-14H","Eagle Ford","Simulated"],["North Sea Inj.","NS-INJ-07","North Sea","Draft"]].map(([p,w,f,st],i)=>(<tr key={i} style={{background:i%2===0?G.bg2:G.bg,borderBottom:`0.5px solid ${G.border}`}}><td style={{padding:"7px 10px",fontWeight:500}}>{p}</td><td style={{padding:"7px 10px",color:G.text2}}>{w}</td><td style={{padding:"7px 10px",color:G.text2}}>{f}</td><td style={{padding:"7px 10px"}}><Bdg level={st==="Active"?"OK":st==="Simulated"?"Info":"Warning"}/></td><td style={{padding:"7px 10px"}}><button onClick={()=>onNav("input")} style={{padding:"3px 10px",background:G.accent,color:"#fff",border:"none",borderRadius:G.r,fontSize:11,cursor:"pointer"}}>Open</button></td></tr>))}</tbody></table></Card></div></div>;}

// ═══════════════════════════════════════════════════════════════════════
// ROOT
// ═══════════════════════════════════════════════════════════════════════
export default function CemOPTI(){const[loggedIn,setLoggedIn]=useState(false);const[nav,setNav]=useState("dashboard");const[inp,setInp]=useState(DEFAULT_INPUT);const[results,setResults]=useState(null);const[running,setRunning]=useState(false);
const doRun=useCallback(()=>{setRunning(true);setTimeout(()=>{try{const t0=performance.now();const r=runSimulation(inp);r.run_time_seconds=+((performance.now()-t0)/1000).toFixed(3);setResults(r);setNav("output");}catch(e){console.error(e);}setRunning(false);},60);},[inp]);
const handleNav=(id)=>{if(id==="logout"){setLoggedIn(false);setNav("dashboard");return;}if(id==="run"){doRun();return;}if(id==="output"&&!results){doRun();return;}setNav(id);};
if(!loggedIn)return <div style={{width:"100%",height:860,borderRadius:12,overflow:"hidden"}}><LoginPage onLogin={()=>{setLoggedIn(true);setNav("dashboard");}}/></div>;
const content=()=>{if(nav==="output"&&results)return <OutputPage results={results} inputs={inp} onBack={()=>setNav("input")}/>;if(nav==="input")return <InputPage inp={inp} setInp={setInp} onRun={doRun} running={running}/>;if(nav==="dashboard")return <Dashboard onNav={handleNav}/>;if(nav==="manuals")return <ManualPage/>;if(nav==="help")return <HelpPage/>;if(nav==="casestudy")return <CaseStudyPage/>;return <div style={{display:"flex",flexDirection:"column",height:"100%",overflow:"hidden"}}><Topbar/><div style={{flex:1,display:"flex",alignItems:"center",justifyContent:"center",flexDirection:"column",gap:12,color:G.text2}}><div style={{fontSize:14,fontWeight:500,color:G.text}}>{NAVS.find(n=>n.id===nav)?.l||nav}</div><button onClick={()=>setNav("input")} style={{padding:"7px 16px",background:G.accent,color:"#fff",border:"none",borderRadius:G.r,fontSize:12,cursor:"pointer"}}>Go to Input Data</button></div></div>;};
return <div style={{display:"flex",height:860,border:`0.5px solid ${G.border}`,borderRadius:12,overflow:"hidden",background:G.bg3,fontFamily:"var(--font-sans)",fontSize:13,color:G.text}}><Sidebar nav={nav} setNav={handleNav}/><div style={{flex:1,display:"flex",flexDirection:"column",overflow:"hidden"}}>{content()}</div></div>;}
